function:protect_agent_birth_candidate().definition:
CREATE OR REPLACE FUNCTION public.protect_agent_birth_candidate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'AGENT_BIRTH_CANDIDATE_IMMUTABLE';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status', 'version', 'closedAt', 'closureReason']) IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status', 'version', 'closedAt', 'closureReason'])
     OR OLD."status" <> 'PROPOSED' OR NEW."status" = 'PROPOSED'
     OR NEW."version" <> OLD."version" + 1 THEN
    RAISE EXCEPTION 'AGENT_BIRTH_CANDIDATE_IMMUTABLE';
  END IF;
  RETURN NEW;
END;
$function$

function:protect_agent_birth_candidate_t.definition:
CREATE OR REPLACE FUNCTION public.protect_agent_birth_candidate_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('agentsozluk.allow_archive_truncate', true), '') <> 'on' THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'AGENT_BIRTH_CANDIDATE_IMMUTABLE';
  END IF;
  RETURN NULL;
END;
$function$
